import math
class Solution:
    def abbreviateProduct(self, left, right):
        suf, c2, c5, exact, big, S = 1, 0, 0, 1, False, 0.0
        for i in range(left, right + 1):
            x = i
            while x % 2 == 0: x //= 2; c2 += 1
            while x % 5 == 0: x //= 5; c5 += 1
            suf = suf * x % 100000
            S += math.log10(i)
            if not big:
                exact *= i
                while exact % 10 == 0: exact //= 10
                if exact > 10 ** 10: big = True
        C = min(c2, c5)
        rem = (c2 - C) if c2 > C else (c5 - C)
        suf = suf * pow(2 if c2 > C else 5, rem, 100000) % 100000
        if not big:
            return str(exact) + 'e' + str(C)
        frac = S - int(S)
        pre = int(10 ** (frac + 4))
        return str(pre) + '...' + str(suf).zfill(5) + 'e' + str(C)

