    string abbreviateProduct(int left, int right) {
        long long suf = 1, c2 = 0, c5 = 0, exact = 1;
        bool big = false; double S = 0;
        for (long long i = left; i <= right; i++) {
            long long x = i;
            while (x % 2 == 0) { x /= 2; c2++; }
            while (x % 5 == 0) { x /= 5; c5++; }
            suf = suf * x % 100000;
            S += log10((double)i);
            if (!big) {
                exact *= i;
                while (exact % 10 == 0) exact /= 10;
                if (exact > 10000000000LL) big = true;
            }
        }
        long long C = min(c2, c5);
        long long rem = c2 > C ? c2 - C : c5 - C;
        long long r = 1, b = c2 > C ? 2 : 5, p = rem;
        while (p) { if (p & 1) r = r * b % 100000; b = b * b % 100000; p >>= 1; }
        suf = suf * r % 100000;
        if (!big) return to_string(exact) + "e" + to_string(C);
        double frac = S - floor(S);
        long long pre = (long long)pow(10.0, frac + 4);
        char buf[8]; sprintf(buf, "%05lld", suf);
