        long suf = 1, c2 = 0, c5 = 0, exact = 1;
        boolean big = false; double S = 0;
        for (long i = left; i <= right; i++) {
            long x = i;
            while (x % 2 == 0) { x /= 2; c2++; }
            while (x % 5 == 0) { x /= 5; c5++; }
            suf = suf * x % 100000;
            S += Math.log10(i);
            if (!big) {
                exact *= i;
                while (exact % 10 == 0) exact /= 10;
                if (exact > 10000000000L) big = true;
            }
        }
        long C = Math.min(c2, c5);
        long rem = c2 > C ? c2 - C : c5 - C;
        long r = 1, b = c2 > C ? 2 : 5, p = rem;
        while (p > 0) { if ((p & 1) == 1) r = r * b % 100000; b = b * b % 100000; p >>= 1; }
        suf = suf * r % 100000;
        if (!big) return exact + "e" + C;
        double frac = S - Math.floor(S);
        long pre = (long) Math.pow(10, frac + 4);
        return pre + "..." + String.format("%05d", suf) + "e" + C;
    }
}

