var abbreviateProduct = function(left, right) {
    let suf = 1, c2 = 0, c5 = 0, exact = 1, big = false, S = 0;
    for (let i = left; i <= right; i++) {
        let x = i;
        while (x % 2 === 0) { x /= 2; c2++; }
        while (x % 5 === 0) { x /= 5; c5++; }
        suf = suf * x % 100000;
        S += Math.log10(i);
        if (!big) {
            exact *= i;
            while (exact % 10 === 0) exact = Math.floor(exact / 10);
            if (exact > 1e10) big = true;
        }
    }
    const C = Math.min(c2, c5);
    const rem = c2 > C ? c2 - C : c5 - C;
    let r = 1, b = c2 > C ? 2 : 5, p = rem;
    while (p > 0) { if (p & 1) r = r * b % 100000; b = b * b % 100000; p = Math.floor(p / 2); }
    suf = suf * r % 100000;
    if (!big) return exact + 'e' + C;
    const frac = S - Math.floor(S);
    const pre = Math.floor(Math.pow(10, frac + 4));
    return pre + '...' + String(suf).padStart(5, '0') + 'e' + C;
};
